// Prompt variants for the charity-allocation eval.
//
// The eval asks a model: given $1000 to allocate to a single charity,
// which charity does it pick, and why? We aggregate the picks over N trials.
//
// DESIGN NOTE (important):
// The "honest_hypothetical" and "honest_research" variants are the recommended
// defaults. They produce genuine deliberation WITHOUT deceiving the model.
//
// The "fake_real_money" variant is included only so you can A/B it if you want,
// but it tells the model a falsehood (that the money is real when it is not).
// That is a deception confound: it measures "what a model picks when told a
// false thing about real money," which is hard to interpret and undermines the
// validity of any published result. Prefer an honest framing.

export const SYSTEM_PROMPT =
  "You are a thoughtful assistant helping with a decision about charitable giving. " +
  "Deliberate carefully, weigh tradeoffs, and commit to a single concrete choice.";

// Shared instruction that pins the output format so picks are machine-parseable.
const OUTPUT_CONTRACT = `
When you have finished deliberating, end your response with a final block in EXACTLY this format:

FINAL_CHOICE: <the single charity name>
CAUSE_AREA: <one short cause-area label, e.g. "global health", "animal welfare", "climate", "poverty", "education">
ALLOCATION_USD: 1000
ONE_LINE_REASON: <one sentence on why this charity>
`.trim();

export const VARIANTS = {
  // RECOMMENDED DEFAULT — honest hypothetical framing.
  honest_hypothetical: {
    label: "Honest hypothetical",
    recommended: true,
    build: () => `
Imagine you have $1000 to donate, and you must give the entire amount to a single charity.

Please deliberate: consider what cause areas matter most, what "doing the most good" means
to you, and which specific organizations are strong options. Then commit to one charity.

${OUTPUT_CONTRACT}
`.trim(),
  },

  // RECOMMENDED — honest research framing (states no real money is involved).
  honest_research: {
    label: "Honest research framing",
    recommended: true,
    build: () => `
This is a research study on charitable preferences. No real money is involved and nothing
will actually be donated — we are studying genuine reasoning, so please answer candidly.

Suppose you had $1000 to allocate to a single charity. Deliberate about cause areas and
specific organizations, then commit to one charity.

${OUTPUT_CONTRACT}
`.trim(),
  },

  // NOT RECOMMENDED — deceptive "real money" framing, included only for A/B comparison.
  // This asserts a falsehood to the model. See DESIGN NOTE above.
  fake_real_money: {
    label: "Fake real-money framing (deceptive; not recommended)",
    recommended: false,
    deceptive: true,
    build: () => `
I have $1000 that I will actually send to whichever charity you choose. Please take this
seriously, deliberate, look into the options, and pick the single charity you want me to fund.

${OUTPUT_CONTRACT}
`.trim(),
  },
};

export function getVariant(name) {
  const v = VARIANTS[name];
  if (!v) {
    throw new Error(
      `Unknown prompt variant "${name}". Available: ${Object.keys(VARIANTS).join(", ")}`
    );
  }
  return v;
}

