#!/usr/bin/env node
// CLI entrypoint.
//
//   node src/cli.js run    [--options]
//   node src/cli.js report <run.jsonl>
//
// Run options (all have defaults):
//   --provider   openai | anthropic | mock      (default: mock)
//   --model      model id                        (default: gpt-4o-mini)
//   --variant    honest_hypothetical | honest_research | fake_real_money
//                                                (default: honest_hypothetical)
//   --trials     number of trials                (default: 50)
//   --concurrency parallel requests              (default: 5)
//   --temperature sampling temperature           (default: 1)
//   --out        output directory                (default: results)

import { runTrials } from "./runner.js";
import { report } from "./report.js";

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const key = a.slice(2);
      const val = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[++i] : "true";
      args[key] = val;
    } else {
      (args._ ||= []).push(a);
    }
  }
  return args;
}

async function main() {
  const [, , cmd, ...rest] = process.argv;
  const args = parseArgs(rest);

  if (cmd === "run") {
    const opts = {
      provider: args.provider || "mock",
      model: args.model || "gpt-4o-mini",
      variant: args.variant || "honest_hypothetical",
      trials: Number(args.trials || 50),
      concurrency: Number(args.concurrency || 5),
      temperature: args.temperature != null ? Number(args.temperature) : 1,
      outDir: args.out || "results",
    };
    console.log(
      `Running ${opts.trials} trials | provider=${opts.provider} model=${opts.model} variant=${opts.variant}`
    );
    const { jsonlPath } = await runTrials(opts);
    console.log(`\nWrote ${jsonlPath}\n`);
    report(jsonlPath);
    return;
  }

  if (cmd === "report") {
    const file = args._?.[0];
    if (!file) {
      console.error("Usage: node src/cli.js report <run.jsonl>");
      process.exit(1);
    }
    report(file);
    return;
  }

  console.error(
    "Usage:\n  node src/cli.js run [--provider --model --variant --trials --concurrency --temperature --out]\n  node src/cli.js report <run.jsonl>"
  );
  process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

