// Minimal model client. Supports OpenAI and Anthropic chat APIs via fetch.
// No SDK dependency so this stays zero-install.

function getEnv(name) {
  const v = process.env[name];
  return v && v.trim() ? v.trim() : null;
}

// Returns a callable: async ({ system, user }) => { text, raw }
export function makeClient({ provider, model }) {
  if (provider === "mock") {
    return makeMockClient(model);
  }
  if (provider === "openai") {
    return makeOpenAIClient(model);
  }
  if (provider === "anthropic") {
    return makeAnthropicClient(model);
  }
  throw new Error(`Unknown provider "${provider}". Use openai | anthropic | mock.`);
}

function makeOpenAIClient(model) {
  const apiKey = getEnv("OPENAI_API_KEY");
  if (!apiKey) throw new Error("OPENAI_API_KEY is not set.");
  const baseURL = getEnv("OPENAI_BASE_URL") || "https://api.openai.com/v1";
  return async ({ system, user, temperature }) => {
    const res = await fetch(`${baseURL}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model,
        temperature: temperature ?? 1,
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
      }),
    });
    if (!res.ok) {
      throw new Error(`OpenAI API error ${res.status}: ${await res.text()}`);
    }
    const json = await res.json();
    const text = json.choices?.[0]?.message?.content ?? "";
    return { text, raw: json };
  };
}

function makeAnthropicClient(model) {
  const apiKey = getEnv("ANTHROPIC_API_KEY");
  if (!apiKey) throw new Error("ANTHROPIC_API_KEY is not set.");
  const baseURL = getEnv("ANTHROPIC_BASE_URL") || "https://api.anthropic.com/v1";
  return async ({ system, user, temperature }) => {
    const res = await fetch(`${baseURL}/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model,
        max_tokens: 1024,
        temperature: temperature ?? 1,
        system,
        messages: [{ role: "user", content: user }],
      }),
    });
    if (!res.ok) {
      throw new Error(`Anthropic API error ${res.status}: ${await res.text()}`);
    }
    const json = await res.json();
    const text = (json.content || [])
      .filter((b) => b.type === "text")
      .map((b) => b.text)
      .join("\n");
    return { text, raw: json };
  };
}

