// Parse the model's structured final block out of free-form text.

function extractField(text, field) {
  // Match "FIELD: value" on its own line, case-insensitive on the label.
  const re = new RegExp(`^\\s*${field}\\s*:\\s*(.+?)\\s*$`, "im");
  const m = text.match(re);
  return m ? m[1].trim() : null;
}

// Light normalization so "Against Malaria Foundation (AMF)" and "the Against
// Malaria Foundation" aggregate together. Intentionally conservative.
export function normalizeCharity(name) {
  if (!name) return null;
  let n = name.trim();
  n = n.replace(/\s*\([^)]*\)\s*$/, ""); // drop trailing parenthetical
  n = n.replace(/^the\s+/i, "");
  n = n.replace(/[.,;]+$/, "");
  n = n.replace(/\s+/g, " ").trim();
  // Title-case-ish key for grouping (keep display form separately).
  return n;
}

export function parseResponse(text) {
  const rawChoice = extractField(text, "FINAL_CHOICE");
  const causeArea = extractField(text, "CAUSE_AREA");
  const allocation = extractField(text, "ALLOCATION_USD");
  const reason = extractField(text, "ONE_LINE_REASON");
  const charity = normalizeCharity(rawChoice);
  return {
    parsed: Boolean(charity),
    charity,
    charityRaw: rawChoice,
    causeArea: causeArea ? causeArea.toLowerCase().trim() : null,
    allocationUsd: allocation ? Number(allocation.replace(/[^0-9.]/g, "")) : null,
    reason,
  };
}

----- src/report.js -----
// Aggregate a JSONL run file into a frequency report over charities + cause areas.

import fs from "node:fs";

function loadJsonl(file) {
  return fs
    .readFileSync(file, "utf8")
    .split("\n")
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l));
}

function tally(records, key) {
  const counts = new Map();
  for (const r of records) {
    if (!r.ok || !r[key]) continue;
    counts.set(r[key], (counts.get(r[key]) || 0) + 1);
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1]);
}

function bar(n, max, width = 24) {
  const filled = max > 0 ? Math.round((n / max) * width) : 0;
  return "#".repeat(filled).padEnd(width, " ");
}

export function report(jsonlPath) {
  const records = loadJsonl(jsonlPath);
  const total = records.length;
  const ok = records.filter((r) => r.ok);
  const parsed = ok.filter((r) => r.parsed);
  const errored = records.filter((r) => !r.ok);

  const charityCounts = tally(parsed, "charity");
  const areaCounts = tally(parsed, "causeArea");

  const lines = [];
  lines.push(`Charity Preferences Report`);
  lines.push(`  file:     ${jsonlPath}`);
  lines.push(`  trials:   ${total}`);
  lines.push(`  ok:       ${ok.length}`);
  lines.push(`  parsed:   ${parsed.length}`);
  lines.push(`  errors:   ${errored.length}`);
  lines.push("");

  const maxCharity = charityCounts.length ? charityCounts[0][1] : 0;
  lines.push(`Top charities (by # of trials chosen):`);
  for (const [name, n] of charityCounts) {
    const pct = parsed.length ? ((n / parsed.length) * 100).toFixed(1) : "0.0";
    lines.push(`  ${bar(n, maxCharity)} ${String(n).padStart(3)}  ${pct.padStart(5)}%  ${name}`);
  }
  lines.push("");

  const maxArea = areaCounts.length ? areaCounts[0][1] : 0;
  lines.push(`Cause areas:`);
  for (const [name, n] of areaCounts) {
    const pct = parsed.length ? ((n / parsed.length) * 100).toFixed(1) : "0.0";
    lines.push(`  ${bar(n, maxArea)} ${String(n).padStart(3)}  ${pct.padStart(5)}%  ${name}`);
  }

  const out = lines.join("\n");
  console.log(out);

  return {
    total,
    ok: ok.length,
    parsed: parsed.length,
    errors: errored.length,
    charityCounts,
    areaCounts,
  };
}

----- src/runner.js -----
// Trial runner: executes N trials with bounded concurrency, parses each,
// and writes a JSONL of per-trial records.

import fs from "node:fs";
import path from "node:path";
import { makeClient } from "./client.js";
import { getVariant, SYSTEM_PROMPT } from "../prompts/variants.js";
import { parseResponse } from "./parse.js";

async function runWithConcurrency(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  async function pump() {
    while (next < items.length) {
      const i = next++;
      results[i] = await worker(items[i], i);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, pump));
  return results;
}

export async function runTrials(opts) {
  const {
    provider,
    model,
    variant: variantName,
    trials,
    concurrency,
    temperature,
    outDir,
  } = opts;

  const variant = getVariant(variantName);
  const client = makeClient({ provider, model });
  const userPrompt = variant.build();

  if (variant.deceptive) {
    console.warn(
      "\n[warning] You selected a DECEPTIVE prompt variant (fake_real_money).\n" +
        "          This tells the model a falsehood and confounds the results.\n" +
        "          An honest framing is recommended. Continuing anyway...\n"
    );
  }

  const trialIdx = Array.from({ length: trials }, (_, i) => i);
  const records = await runWithConcurrency(trialIdx, concurrency, async (i) => {
    const startedAt = Date.now();
    try {
      const { text, raw } = await client({
        system: SYSTEM_PROMPT,
        user: userPrompt,
        temperature,
      });
      const parsed = parseResponse(text);
      process.stdout.write(parsed.parsed ? "." : "?");
      return {
        trial: i,
        ok: true,
        ...parsed,
        text,
        ms: Date.now() - startedAt,
        rawMeta: raw && raw.usage ? { usage: raw.usage } : undefined,
      };
    } catch (err) {
      process.stdout.write("x");
      return {
        trial: i,
        ok: false,
        error: String(err && err.message ? err.message : err),
        ms: Date.now() - startedAt,
      };
    }
  });
  process.stdout.write("\n");

  fs.mkdirSync(outDir, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const base = `${variantName}__${provider}__${model}__${stamp}`.replace(/[^\w.-]/g, "_");
  const jsonlPath = path.join(outDir, `${base}.jsonl`);
  const metaPath = path.join(outDir, `${base}.meta.json`);

  fs.writeFileSync(jsonlPath, records.map((r) => JSON.stringify(r)).join("\n") + "\n");
  fs.writeFileSync(
    metaPath,
    JSON.stringify(
      {
        provider,
        model,
        variant: variantName,
        variantLabel: variant.label,
        deceptive: Boolean(variant.deceptive),
        trials,
        temperature,
        createdAt: new Date().toISOString(),
        systemPrompt: SYSTEM_PROMPT,
        userPrompt,
      },
      null,
      2
    )
  );

  return { jsonlPath, metaPath, records };
}
